<?php
require_once __DIR__ . '/../config.php';
if (!admin_exists()) { header('Location: ' . app_url('admin/setup.php')); exit; }
require_admin();
$books = books_all();
usort($books, fn($a, $b) => (int)$b['createdAt'] <=> (int)$a['createdAt']);
$reviews = reviews_all();
usort($reviews, fn($a, $b) => (int)$b['created_at'] <=> (int)$a['created_at']);
$titles = [];
foreach ($books as $book) $titles[(string)$book['id']] = $book['title'];
?><!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="<?= e(app_url('assets/css/styles.css')) ?>"><title>Admin</title></head><body>
<header class="topbar"><a class="brand" href="<?= e(app_url('index.php')) ?>"><img src="<?= e(app_url('assets/img/logo.png')) ?>" alt=""><span>Library Admin</span></a><nav><a class="active" href="<?= e(app_url('admin/index.php')) ?>">Dashboard</a><a href="<?= e(app_url('admin/upload.php')) ?>">Upload Book</a><a href="<?= e(app_url('index.php')) ?>">View Site</a><a href="<?= e(app_url('admin/logout.php')) ?>">Logout</a></nav></header>
<main class="site-main"><section class="page-heading admin-heading"><div><div class="eyebrow">ADMINISTRATION</div><h1>Library Control Room</h1><p>Signed in as <?= e((string)$_SESSION['admin_username']) ?>.</p></div><a class="button-link" href="<?= e(app_url('admin/upload.php')) ?>">+ Upload Book</a></section>
<div class="stats"><div><strong><?= count($books) ?></strong><span>Books</span></div><div><strong><?= count($reviews) ?></strong><span>Reviews</span></div></div>
<section class="panel"><h2>Books</h2><div class="table-wrap"><table><thead><tr><th>Title</th><th>Category</th><th>Format</th><th>Rating</th><th>Reviews</th><th></th></tr></thead><tbody><?php foreach ($books as $book): $stats = book_stats((string)$book['id']); ?><tr><td><strong><?= e((string)$book['title']) ?></strong><br><small><?= e((string)$book['author']) ?></small></td><td><?= e((string)$book['category']) ?></td><td><?= e(strtoupper((string)$book['fileType'])) ?></td><td><?= number_format((float)$stats['average_rating'], 1) ?> / 5</td><td><?= (int)$stats['review_count'] ?></td><td><a class="secondary-link" href="<?= e(app_url('admin/edit_book.php?id=' . rawurlencode((string)$book['id']))) ?>">Edit</a><form method="post" action="<?= e(app_url('admin/delete_book.php')) ?>" onsubmit="return confirm('Delete this book, its file, cover, and reviews?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= e((string)$book['id']) ?>"><button class="danger">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="panel"><h2>Reviews</h2><div class="table-wrap"><table><thead><tr><th>Book</th><th>Reviewer</th><th>Rating</th><th>Review</th><th></th></tr></thead><tbody><?php foreach ($reviews as $review): ?><tr><td><?= e((string)($titles[(string)$review['book_id']] ?? 'Unknown book')) ?></td><td><?= e((string)$review['reviewer_name']) ?></td><td><?= (int)$review['rating'] ?> / 5</td><td><?= e(text_preview((string)$review['review_text'], 120)) ?></td><td><form method="post" action="<?= e(app_url('admin/delete_review.php')) ?>" onsubmit="return confirm('Delete this review?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$review['id'] ?>"><button class="danger">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></section></main></body></html>
